            <input type="date" value={dataEntrada} onChange={e => setDataEntrada(e.target.value)} style={{
              width: '100%', border: 'none', outline: 'none', background: 'transparent',
              fontSize: 15, color: 'var(--ink)', fontFamily: 'var(--sans)', padding: 0,
            }} />
